def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    value = (v1 + v2) / 2
    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "average": value,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
